"""Strict reader for locally synchronized platform metadata."""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


class MetadataCacheError(ValueError):
    """The local metadata cache is absent or internally inconsistent."""


class MetadataCacheMissing(MetadataCacheError):
    pass


class MetadataCacheStale(MetadataCacheError):
    pass


@dataclass(frozen=True)
class OperatorMetadata:
    name: str
    signature: str
    arity: int
    description: str


@dataclass(frozen=True)
class FieldMetadata:
    field_id: str
    dataset_id: str
    field_type: str
    category: str
    description: str


@dataclass(frozen=True)
class DatasetMetadata:
    dataset_id: str
    name: str
    category: str


@dataclass(frozen=True)
class MetadataCache:
    cache_dir: Path
    operators: dict[str, OperatorMetadata]
    fields: dict[str, FieldMetadata]
    datasets: dict[str, DatasetMetadata]
    info: dict[str, Any]

    @classmethod
    def load(
        cls,
        cache_dir: Path | str,
        *,
        max_age_hours: float = 168,
        allow_stale: bool = False,
    ) -> "MetadataCache":
        root = Path(cache_dir)
        names = {
            "operators": "操作符.json",
            "data_fields": "数据字段.json",
            "datasets": "数据集.json",
            "info": "缓存信息.json",
        }
        missing = [name for name in names.values() if not (root / name).is_file()]
        if missing:
            raise MetadataCacheMissing(f"平台元数据缓存缺失: {', '.join(missing)}")

        payloads: dict[str, Any] = {}
        for key, filename in names.items():
            try:
                payloads[key] = json.loads((root / filename).read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError) as exc:
                raise MetadataCacheError(f"无法读取平台元数据缓存 {filename}: {exc}") from exc

        info = _mapping(payloads["info"], "缓存信息.json")
        expected_schema = str(info.get("schema_version") or "")
        if not expected_schema:
            raise MetadataCacheError("缓存信息缺少 schema_version")

        records: dict[str, list[dict[str, Any]]] = {}
        for key in ("operators", "data_fields", "datasets"):
            document = _mapping(payloads[key], names[key])
            if str(document.get("schema_version") or "") != expected_schema:
                raise MetadataCacheError(f"{names[key]} schema_version 与缓存信息不一致")
            raw_records = document.get("records")
            if not isinstance(raw_records, list) or not all(isinstance(row, dict) for row in raw_records):
                raise MetadataCacheError(f"{names[key]} records 必须为对象数组")
            records[key] = raw_records

        counts = _mapping(info.get("record_counts"), "缓存信息.record_counts")
        for key, rows in records.items():
            if int(counts.get(key, -1)) != len(rows):
                raise MetadataCacheError(f"{key} 记录数量与缓存信息不一致")

        hashed = {key: payloads[key] for key in ("operators", "data_fields", "datasets")}
        actual_hash = hashlib.sha256(
            json.dumps(hashed, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        if str(info.get("content_hash") or "") != actual_hash:
            raise MetadataCacheError("平台元数据缓存 content_hash 校验失败")

        fetched_at = _parse_time(str(info.get("fetched_at") or ""))
        age_hours = (datetime.now(timezone.utc) - fetched_at).total_seconds() / 3600
        if age_hours > float(max_age_hours) and not allow_stale:
            raise MetadataCacheStale(
                f"平台元数据缓存已过期: {age_hours:.1f} 小时，限制 {max_age_hours:g} 小时"
            )

        operators: dict[str, OperatorMetadata] = {}
        for row in records["operators"]:
            name = _required_text(row, "name", "操作符")
            signature = _required_text(row, "signature", name)
            try:
                arity = int(row["arity"])
            except (KeyError, TypeError, ValueError) as exc:
                raise MetadataCacheError(f"操作符 {name} 缺少有效 arity") from exc
            if arity < 0:
                raise MetadataCacheError(f"操作符 {name} 的 arity 无效")
            operators[name.lower()] = OperatorMetadata(
                name=name.lower(), signature=signature, arity=arity,
                description=str(row.get("description") or ""),
            )

        datasets: dict[str, DatasetMetadata] = {}
        for row in records["datasets"]:
            dataset_id = _required_text(row, "id", "数据集")
            datasets[dataset_id] = DatasetMetadata(
                dataset_id=dataset_id,
                name=str(row.get("name") or dataset_id),
                category=str(row.get("category") or "unknown").lower(),
            )

        fields: dict[str, FieldMetadata] = {}
        for row in records["data_fields"]:
            field_id = _required_text(row, "id", "数据字段")
            dataset_id = _required_text(row, "dataset_id", field_id)
            if dataset_id not in datasets:
                raise MetadataCacheError(f"字段 {field_id} 引用了未知数据集 {dataset_id}")
            field_type = _required_text(row, "type", field_id).upper()
            fields[field_id] = FieldMetadata(
                field_id=field_id,
                dataset_id=dataset_id,
                field_type=field_type,
                category=str(row.get("category") or "unknown").lower(),
                description=str(row.get("description") or ""),
            )
        if not operators or not fields or not datasets:
            raise MetadataCacheError("平台元数据缓存不得为空")
        return cls(root, operators, fields, datasets, info)


def _mapping(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise MetadataCacheError(f"{label} 必须为 JSON 对象")
    return value


def _required_text(row: dict[str, Any], key: str, label: str) -> str:
    value = str(row.get(key) or "").strip()
    if not value:
        raise MetadataCacheError(f"{label} 缺少 {key}")
    return value


def _parse_time(value: str) -> datetime:
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise MetadataCacheError("缓存信息 fetched_at 无效") from exc
    if parsed.tzinfo is None:
        raise MetadataCacheError("缓存信息 fetched_at 必须包含时区")
    return parsed.astimezone(timezone.utc)

"""Local FASTEXPR validation against synchronized metadata."""

from __future__ import annotations

from dataclasses import dataclass

from alpha_mining.domain.expression_ast import AstNode, ExpressionSyntaxError, parse_expression
from alpha_mining.offline.metadata import MetadataCache


@dataclass(frozen=True)
class ValidationIssue:
    code: str
    message: str


class LocalExpressionValidator:
    def __init__(self, metadata: MetadataCache) -> None:
        self.metadata = metadata

    def validate(self, expression: str) -> list[ValidationIssue]:
        try:
            root = parse_expression(expression)
        except ExpressionSyntaxError as exc:
            return [ValidationIssue("INVALID_SYNTAX", str(exc))]
        issues: list[ValidationIssue] = []

        def walk(node: AstNode, *, callee: bool = False) -> None:
            if node.kind == "call":
                operator = self.metadata.operators.get(node.value)
                if operator is None:
                    issues.append(ValidationIssue("UNKNOWN_OPERATOR", node.value))
                elif len(node.children) != operator.arity:
                    issues.append(
                        ValidationIssue(
                            "INVALID_ARITY",
                            f"{node.value} expects {operator.arity}, got {len(node.children)}",
                        )
                    )
                for child in node.children:
                    walk(child)
                return
            if node.kind == "ident" and not callee and node.value not in self.metadata.fields:
                issues.append(ValidationIssue("UNKNOWN_FIELD", node.value))
            for child in node.children:
                walk(child)

        walk(root)
        return issues

"""Single-writer CSV candidate queue with append-only status events."""

from __future__ import annotations

import csv
import json
import os
import time
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Iterator


CANDIDATE_FIELDS = (
    "candidate_id", "created_at", "updated_at", "expression", "alpha_type",
    "region", "universe", "delay", "decay", "neutralization", "truncation",
    "language", "data_fields", "datasets", "operator_family",
    "canonical_signature", "generator_source", "parent_template",
    "economic_hypothesis", "description_draft", "local_score", "priority_score",
    "queue_status", "alpha_id", "retry_count", "last_error_category", "last_error",
)

EVENT_FIELDS = (
    "event_id", "candidate_id", "event_at", "old_status", "new_status", "details",
)


class QueueLockedError(RuntimeError):
    pass


class CandidateCsvQueue:
    def __init__(
        self, queue_path: Path | str, events_path: Path | str,
        *, stale_lock_seconds: float = 3600,
    ) -> None:
        self.queue_path = Path(queue_path)
        self.events_path = Path(events_path)
        self.lock_path = self.queue_path.with_suffix(self.queue_path.suffix + ".lock")
        self.stale_lock_seconds = float(stale_lock_seconds)
        self._owns_lock = False

    @contextmanager
    def writer(self) -> Iterator["CandidateCsvQueue"]:
        self.queue_path.parent.mkdir(parents=True, exist_ok=True)
        self.events_path.parent.mkdir(parents=True, exist_ok=True)
        self._acquire_lock()
        try:
            yield self
        finally:
            if self._owns_lock:
                try:
                    self.lock_path.unlink()
                except FileNotFoundError:
                    pass
                self._owns_lock = False

    def empty_candidate(self) -> dict[str, str]:
        return {field: "" for field in CANDIDATE_FIELDS}

    def read(self) -> list[dict[str, str]]:
        return self._read_csv(self.queue_path)

    def read_events(self) -> list[dict[str, str]]:
        return self._read_csv(self.events_path)

    def upsert(self, candidate: dict[str, str]) -> None:
        self._require_lock()
        row = self.empty_candidate()
        row.update({key: str(value) for key, value in candidate.items() if key in row})
        if not row["candidate_id"]:
            raise ValueError("candidate_id is required")
        now = _utc_now()
        row["created_at"] = row["created_at"] or now
        row["updated_at"] = now
        rows = self.read()
        previous = next((item for item in rows if item["candidate_id"] == row["candidate_id"]), None)
        if previous:
            row["created_at"] = previous["created_at"]
            rows = [row if item["candidate_id"] == row["candidate_id"] else item for item in rows]
        else:
            rows.append(row)
        self._atomic_write(rows)
        self._append_event(
            row["candidate_id"], previous["queue_status"] if previous else "",
            row["queue_status"], "candidate upserted",
        )

    def transition(self, candidate_id: str, new_status: str, details: str = "") -> None:
        self._require_lock()
        rows = self.read()
        for row in rows:
            if row["candidate_id"] == candidate_id:
                old_status = row["queue_status"]
                row["queue_status"] = new_status
                row["updated_at"] = _utc_now()
                self._atomic_write(rows)
                self._append_event(candidate_id, old_status, new_status, details)
                return
        raise KeyError(candidate_id)

    def _acquire_lock(self) -> None:
        if self.lock_path.exists():
            age = time.time() - self.lock_path.stat().st_mtime
            if age <= self.stale_lock_seconds:
                raise QueueLockedError(f"候选队列正被其他写进程占用: {self.lock_path}")
            self.lock_path.unlink()
        payload = json.dumps({"pid": os.getpid(), "created_at": _utc_now()}, ensure_ascii=False)
        try:
            descriptor = os.open(self.lock_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL)
        except FileExistsError as exc:
            raise QueueLockedError(f"候选队列正被其他写进程占用: {self.lock_path}") from exc
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            handle.write(payload)
        self._owns_lock = True

    def _atomic_write(self, rows: list[dict[str, str]]) -> None:
        temporary = self.queue_path.with_name(self.queue_path.name + ".tmp")
        with temporary.open("w", encoding="utf-8-sig", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=CANDIDATE_FIELDS, extrasaction="ignore")
            writer.writeheader()
            writer.writerows(rows)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, self.queue_path)

    def _append_event(self, candidate_id: str, old: str, new: str, details: str) -> None:
        exists = self.events_path.exists() and self.events_path.stat().st_size > 0
        event_at = _utc_now()
        event_id = f"event_{time.time_ns()}_{os.getpid()}"
        with self.events_path.open("a", encoding="utf-8-sig", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=EVENT_FIELDS)
            if not exists:
                writer.writeheader()
            writer.writerow(
                {"event_id": event_id, "candidate_id": candidate_id, "event_at": event_at,
                 "old_status": old, "new_status": new, "details": details}
            )

    @staticmethod
    def _read_csv(path: Path) -> list[dict[str, str]]:
        if not path.is_file():
            return []
        with path.open(encoding="utf-8-sig", newline="") as handle:
            return list(csv.DictReader(handle))

    def _require_lock(self) -> None:
        if not self._owns_lock:
            raise QueueLockedError("写候选队列前必须持有 lock")


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
